problems.solution:
func fib(n: Int64): Int64 {
    // 滚动变量：递归是 O(2^n)，这里 O(n)
    if (n <= 1) {
        return n
    }
    var prev: Int64 = 0
    var cur: Int64 = 1
    for (i in 2..n + 1) {
        let next = prev + cur
        prev = cur
        cur = next
    }
    return cur
}

