func numIslands(grid: Array<String>): Int64 {
    // 请在这里实现算法（提示：FloodFill——遍历网格，遇到 '1' 计数并感染整片陆地）
    return 0
}

problems.solution:
func numIslands(grid: Array<String>): Int64 {
    // FloodFill：遇到 '1' 计一座岛，并把整片陆地感染成 '0'
    let g = ArrayList<String>()
    for (row in grid) { g.add(row) }
    var count: Int64 = 0
    for (r in 0..g.size) {
        for (c in 0..g[r].size) {
            // 每一步都重读当前行：sink 会改写 g[r]，缓存的字节副本会过期，
            // 把已沉没的陆地再当新岛数一遍（实测重复计数）
            let row = g[r].toArray()
            if (row[c] == 49) {
                count = count + 1
                sink(g, r, c)
            }
        }
    }
    return count
}

// 把 (r,c) 连通的陆地全部染成水
func sink(g: ArrayList<String>, r: Int64, c: Int64): Unit {
    if (r < 0 || r >= g.size || c < 0 || c >= g[r].size) {
        return
    }
    let row = g[r].toArray()
    if (row[c] != 49) {
        return
    }
    row[c] = 48
    g[r] = String.fromUtf8(row.toArray())
    sink(g, r - 1, c)
    sink(g, r + 1, c)
    sink(g, r, c - 1)
    sink(g, r, c + 1)
}

