func findKthLargest(nums: Array<Int64>, k: Int64): Int64 {
    // 请在这里实现算法（提示：排序 / 快速选择 / 手写堆）
    return 0
}

problems.solution:
func findKthLargest(nums: Array<Int64>, k: Int64): Int64 {
    // 快速选择：平均 O(n)
    let a = ArrayList<Int64>()
    for (x in nums) { a.add(x) }
    return quickSelect(a, 0, a.size - 1, a.size - k)
}

func quickSelect(a: ArrayList<Int64>, lo: Int64, hi: Int64, target: Int64): Int64 {
    if (lo == hi) {
        return a[lo]
    }
    // 以 a[hi] 为 pivot 分区
    var store = lo
    var i = lo
    while (i < hi) {
        if (a[i] < a[hi]) {
            let t = a[store]
            a[store] = a[i]
            a[i] = t
            store = store + 1
        }
        i = i + 1
    }
    let t = a[store]
    a[store] = a[hi]
    a[hi] = t
    if (store == target) {
        return a[store]
    } else if (store < target) {
        return quickSelect(a, store + 1, hi, target)
    } else {
        return quickSelect(a, lo, store - 1, target)
    }
}

problems.template:
func topKFrequent(nums: Array<Int64>, k: Int64): Int64 {
    // 请在这里实现算法（提示：计数 + 排序取前 k 个的次数求和）
    return 0
}

problems.solution:
func topKFrequent(nums: Array<Int64>, k: Int64): Int64 {
    // 计数 → 按次数降序取前 k → 求和
    let counts = HashMap<Int64, Int64>()
    for (x in nums) {
        match (counts.get(x)) {
            case Some(c) => counts.add(x, c + 1)
            case None => counts.add(x, 1)
        }
    }
    let freqs = ArrayList<Int64>()
    for ((_, c) in counts) {
        freqs.add(c)
    }
    sortByDesc(freqs)
    var sum: Int64 = 0
    for (i in 0..k) {
        sum = sum + freqs[i]
    }
    return sum
}

func sortByDesc(a: ArrayList<Int64>): Unit {
    for (i in 1..a.size) {
        var j = i
        while (j > 0 && a[j - 1] < a[j]) {
            let t = a[j - 1]
            a[j - 1] = a[j]
            a[j] = t
            j = j - 1
        }
    }
}

